#!/usr/bin/env python3\n\"\"\"\nTest script to verify the stability improvements for rapid UI changes\n\"\"\"\n\nimport time\nfrom vehicle_simulator import VehicleSimulator\nfrom driver_monitor import DriverMonitor\nfrom behavior_analyzer import BehaviorAnalyzer\nfrom decision_engine import AdaptiveDecisionEngine\n\ndef test_stability():\n    print(\"Testing Stability Improvements for Rapid UI Changes\")\n    print(\"=\" * 60)\n    \n    print(\"Changes made:\")\n    print(\"1. Added hysteresis to behavior analyzer to prevent rapid state changes\")\n    print(\"2. Enhanced decision engine with anti-chatter logic\")\n    print(\"3. Improved state transition thresholds\")\n    print()\n    \n    # Initialize all modules\n    vehicle_simulator = VehicleSimulator()\n    driver_monitor = DriverMonitor()\n    behavior_analyzer = BehaviorAnalyzer()\n    decision_engine = AdaptiveDecisionEngine()\n    \n    # Start the simulator\n    vehicle_simulator.start()\n    \n    # Connect modules as done in main.py\n    vehicle_simulator.state_updated.connect(behavior_analyzer.process_vehicle_data)\n    vehicle_simulator.state_updated.connect(decision_engine.update_vehicle_state)\n    driver_monitor.cognitive_state_updated.connect(decision_engine.update_driver_state)\n    behavior_analyzer.behavior_updated.connect(decision_engine.update_behavior_state)\n    \n    print(\"Monitoring for 10 seconds to check stability...\")\n    start_time = time.time()\n    \n    # Track state changes\n    prev_behavior_state = None\n    prev_driver_state = None\n    state_changes = 0\n    \n    while time.time() - start_time < 10:\n        # Get current states\n        current_behavior = behavior_analyzer.get_current_metrics()\n        current_driver = driver_monitor.get_current_state()\n        \n        # Check for changes\n        if (prev_behavior_state != current_behavior.behavior_classification or \n            prev_driver_state != current_driver.state_classification):\n            if prev_behavior_state is not None:  # Don't count initial state\n                state_changes += 1\n                print(f\"State changed at {time.time() - start_time:.1f}s - \"\n                      f\"Behavior: {current_behavior.behavior_classification}, \"\n                      f\"Driver: {current_driver.state_classification}\")\n            \n            prev_behavior_state = current_behavior.behavior_classification\n            prev_driver_state = current_driver.state_classification\n        \n        time.sleep(0.1)  # Small delay to prevent busy-waiting\n    \n    print(f\"\\nResult after 10 seconds:\")\n    print(f\"- Total state changes: {state_changes}\")\n    print(f\"- Average time between changes: {10/state_changes:.2f}s if any occurred\")\n    \n    if state_changes == 0:\n        print(\"- No state changes occurred (this is ideal for stability)\")\n    elif state_changes <= 3:\n        print(\"- Good stability: Low number of state changes\")\n    elif state_changes <= 8:\n        print(\"- Moderate stability: Some state changes but acceptable\")\n    else:\n        print(\"- Poor stability: Too many state changes\")\n    \n    print(\"\\nExpected improvement:\")\n    print(\"- Before: Multiple state changes per second causing UI flickering\")\n    print(\"- After: Significantly reduced state changes for better user experience\")\n    \n    vehicle_simulator.stop()\n\nif __name__ == \"__main__\":\n    test_stability()